#define FG_CONV_L20_NO_MAIN
#include "rtx_oracle.cpp"
#include "custom_bot0_contract.h"
namespace{namespace c=fg_custom_bot0;struct Params{CUdeviceptr w,b;std::uint32_t oc,kh,kw,ic;CUdeviceptr in;std::uint32_t ib,ih,iw,is;CUdeviceptr o0,o1,o2;std::uint32_t ob,oh,ow,os;};static_assert(sizeof(Params)==96);
void Rec(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::vector<std::uint8_t>&i0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::vector<std::uint8_t>&i1,const std::vector<std::uint8_t>&out,std::size_t mm,std::size_t cc){std::ofstream s(p);bool pass=mm==0&&cc==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-bot0-run.v1\",\n  \"backend\": \"rtx-cuda-driver\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<GetCurrentProcessId()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-000068\",\n  \"module_token\": 58,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"function_name\": \"custom_block0_conv_bot0_hf_kernel\",\n  \"grid\": [20, 23, 3],\n  \"block\": [32, 2, 4],\n  \"packed_parameter_bytes\": 96,\n  \"weight_source_token\": 150,\n  \"bias_source_token\": 152,\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-bot0-v1\",\n  \"input_pre_sha256\": \""<<Sha256(i0)<<"\",\n  \"input_post_sha256\": \""<<Sha256(i1)<<"\",\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mm<<",\n  \"canary_mismatched_bytes\": "<<cc<<",\n  \"external_model_files_opened\": true,\n  \"expected_output_file_opened\": false,\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}}
int main(int argc,char**v){if(argc!=7)return 2;try{auto mod=Read(v[1]),w0=Read(v[2]),b0=Read(v[3]);if(mod.size()!=c::kModuleBytes||Sha256(mod)!=c::kModuleSha256||w0.size()!=c::kWeightBytes||Sha256(w0)!=c::kWeightSha256||b0.size()!=c::kBiasBytes||Sha256(b0)!=c::kBiasSha256)throw std::runtime_error("identity");char*e=nullptr;auto q=strtoul(v[6],&e,16);if(e==v[6]||*e||q>255)throw std::runtime_error("poison");auto poison=std::uint8_t(q);std::filesystem::path dir=v[4];std::filesystem::create_directories(dir);auto i0=c::Input();Check(cuInit(0),"init");CUdevice d;Check(cuDeviceGet(&d,0),"dev");CUcontext x;Check(cuDevicePrimaryCtxRetain(&x,d),"ctx");Check(cuCtxSetCurrent(x),"set");CUmodule m;Check(cuModuleLoadData(&m,mod.data()),"module");CUfunction f;Check(cuModuleGetFunction(&f,m,"custom_block0_conv_bot0_hf_kernel"),"fn");GuardedDeviceBuffer w,b,in,o0,o1,o2;w.Allocate(c::kWeightBytes);b.Allocate(c::kBiasBytes);in.Allocate(c::kInputBytes);o0.Allocate(c::kOutputPlaneBytes);o1.Allocate(c::kOutputPlaneBytes);o2.Allocate(c::kOutputPlaneBytes);Check(cuMemcpyHtoD(w.payload(),w0.data(),w0.size()),"w");Check(cuMemcpyHtoD(b.payload(),b0.data(),b0.size()),"b");Check(cuMemcpyHtoD(in.payload(),i0.data(),i0.size()),"in");Check(cuMemsetD8(o0.payload(),poison,c::kOutputPlaneBytes),"o0");Check(cuMemsetD8(o1.payload(),poison,c::kOutputPlaneBytes),"o1");Check(cuMemsetD8(o2.payload(),poison,c::kOutputPlaneBytes),"o2");Params p{w.payload(),b.payload(),32,3,3,64,in.payload(),1,46,80,64,o0.payload(),o1.payload(),o2.payload(),1,92,160,32};std::size_t n=sizeof(p);void*extra[]={CU_LAUNCH_PARAM_BUFFER_POINTER,&p,CU_LAUNCH_PARAM_BUFFER_SIZE,&n,CU_LAUNCH_PARAM_END};Check(cuLaunchKernel(f,20,23,3,32,2,4,0,nullptr,nullptr,extra),"launch");Check(cuCtxSynchronize(),"sync");auto wg=w.ReadAll(),bg=b.ReadAll(),ig=in.ReadAll(),a=o0.ReadAll(),bb=o1.ReadAll(),cc=o2.ReadAll();auto w1=Payload(wg,c::kWeightBytes),b1=Payload(bg,c::kBiasBytes),i1=Payload(ig,c::kInputBytes),oa=Payload(a,c::kOutputPlaneBytes),ob=Payload(bb,c::kOutputPlaneBytes),oc=Payload(cc,c::kOutputPlaneBytes);std::vector<std::uint8_t>out;out.reserve(c::kOutputBytes);out.insert(out.end(),oa.begin(),oa.end());out.insert(out.end(),ob.begin(),ob.end());out.insert(out.end(),oc.begin(),oc.end());auto mm=Mismatches(w0,w1)+Mismatches(b0,b1)+Mismatches(i0,i1);auto can=CanaryMismatches(wg,c::kWeightBytes)+CanaryMismatches(bg,c::kBiasBytes)+CanaryMismatches(ig,c::kInputBytes)+CanaryMismatches(a,c::kOutputPlaneBytes)+CanaryMismatches(bb,c::kOutputPlaneBytes)+CanaryMismatches(cc,c::kOutputPlaneBytes);Rec(dir/"run-receipt.json",v[5],poison,w0,b0,i0,w1,b1,i1,out,mm,can);Write(dir/"output.bin",out);bool pass=mm==0&&can==0;std::cout<<"output_sha256="<<Sha256(out)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}
